// twoSum 一遍哈希：边遍历边查 target-x 是否已经出现过。
func twoSum(nums []int, target int) []int {
	seen := make(map[int]int, len(nums))
	for i, x := range nums {
		if j, ok := seen[target-x]; ok {
			return []int{j, i}
		}
		seen[x] = i
	}
	return nil
}

// subarraySum 前缀和加哈希：sum[j]-sum[i] == k 等价于 sum[i] == sum[j]-k；先放入前缀和 0。
func subarraySum(nums []int, k int) int {
	count := map[int]int{0: 1}
	sum, res := 0, 0
	for _, x := range nums {
		sum += x
		res += count[sum-k]
		count[sum]++
	}
	return res
}

// longestConsecutive 集合法：只从“序列起点”（x-1 不在集合里）开始往后数。
func longestConsecutive(nums []int) int {
	set := make(map[int]struct{}, len(nums))
	for _, x := range nums {
		set[x] = struct{}{}
	}
	best := 0
	for x := range set {
		if _, ok := set[x-1]; ok {
			continue
		}
		length := 1
		for {
			if _, ok := set[x+length]; !ok {
				break
			}
			length++
		}
		if length > best {
			best = length
		}
	}
	return best
}

// lengthOfLongestSubstring 滑动窗口：右指针扩张，窗口内出现重复时左指针收缩。
func lengthOfLongestSubstring(s string) int {
	count := map[byte]int{}
	best, left := 0, 0
	for right := 0; right < len(s); right++ {
		count[s[right]]++
		for count[s[right]] > 1 {
			count[s[left]]--
			left++
		}
		if right-left+1 > best {
			best = right - left + 1
		}
	}
	return best
}

// threeSum 排序加双指针：固定第一个数，左右指针夹逼，三处都要跳过重复值。
func threeSum(nums []int) [][]int {
	sort.Ints(nums)
	var res [][]int
	for i := 0; i < len(nums)-2; i++ {
		if i > 0 && nums[i] == nums[i-1] {
			continue
		}
		l, r := i+1, len(nums)-1
		for l < r {
			sum := nums[i] + nums[l] + nums[r]
			switch {
			case sum < 0:
				l++
			case sum > 0:
				r--
			default:
				res = append(res, []int{nums[i], nums[l], nums[r]})
				for l < r && nums[l] == nums[l+1] {
					l++
				}
				for l < r && nums[r] == nums[r-1] {
					r--
				}
				l++
				r--
			}
		}
	}
	return res
}

// merge 把 nums2 并入 nums1：三个指针从后往前填，避免覆盖还没处理的数据。
func merge(nums1 []int, m int, nums2 []int, n int) {
	i, j, k := m-1, n-1, m+n-1
	for j >= 0 {
		if i >= 0 && nums1[i] > nums2[j] {
			nums1[k] = nums1[i]
			i--
		} else {
			nums1[k] = nums2[j]
			j--
		}
		k--
	}
}

// reverseList 迭代反转链表：prev / cur / next 三个指针。
func reverseList(head *ListNode) *ListNode {
	var prev *ListNode
	cur := head
	for cur != nil {
		next := cur.Next
		cur.Next = prev
		prev = cur
		cur = next
	}
	return prev
}

// mergeTwoLists 合并两个升序链表：哨兵节点加尾指针，谁小接谁。
func mergeTwoLists(a, b *ListNode) *ListNode {
	dummy := &ListNode{}
	tail := dummy
	for a != nil && b != nil {
		if a.Val <= b.Val {
			tail.Next = a
			a = a.Next
		} else {
			tail.Next = b
			b = b.Next
		}
		tail = tail.Next
	}
	if a != nil {
		tail.Next = a
	} else {
		tail.Next = b
	}
	return dummy.Next
}

// hasCycle 快慢指针判环：快指针每次走两步，相遇即有环。
func hasCycle(head *ListNode) bool {
	slow, fast := head, head
	for fast != nil && fast.Next != nil {
		slow = slow.Next
		fast = fast.Next.Next
		if slow == fast {
			return true
		}
	}
	return false
}

// isValid 括号匹配：遇到左括号入栈，遇到右括号必须和栈顶配对。
func isValid(s string) bool {
	pairs := map[byte]byte{')': '(', ']': '[', '}': '{'}
	stack := make([]byte, 0, len(s))
	for i := 0; i < len(s); i++ {
		ch := s[i]
		if open, ok := pairs[ch]; ok {
			if len(stack) == 0 || stack[len(stack)-1] != open {
				return false
			}
			stack = stack[:len(stack)-1]
		} else {
			stack = append(stack, ch)
		}
	}
	return len(stack) == 0
}

// trap 单调递减栈接雨水：遇到更高的柱子时弹出凹槽底，用左右两侧较矮者算这一层的水量。
func trap(height []int) int {
	total := 0
	stack := []int{}
	for i, h := range height {
		for len(stack) > 0 && h > height[stack[len(stack)-1]] {
			bottom := height[stack[len(stack)-1]]
			stack = stack[:len(stack)-1]
			if len(stack) == 0 {
				break
			}
			left := stack[len(stack)-1]
			width := i - left - 1
			total += width * (min(h, height[left]) - bottom)
		}
		stack = append(stack, i)
	}
	return total
}

// decodeString 用两个栈：遇到 '[' 把当前字符串和重复次数压栈，遇到 ']' 弹出并拼接。
func decodeString(s string) string {
	var counts []int
	var prefixes []string
	cur := ""
	num := 0
	for i := 0; i < len(s); i++ {
		ch := s[i]
		switch {
		case ch >= '0' && ch <= '9':
			num = num*10 + int(ch-'0')
		case ch == '[':
			counts = append(counts, num)
			prefixes = append(prefixes, cur)
			num, cur = 0, ""
		case ch == ']':
			times := counts[len(counts)-1]
			prefix := prefixes[len(prefixes)-1]
			counts = counts[:len(counts)-1]
			prefixes = prefixes[:len(prefixes)-1]
			cur = prefix + strings.Repeat(cur, times)
		default:
			cur += string(ch)
		}
	}
	return cur
}

// search 标准二分：闭区间 [lo, hi]，循环条件 lo <= hi，找不到返回 -1。
func search(nums []int, target int) int {
	lo, hi := 0, len(nums)-1
	for lo <= hi {
		mid := lo + (hi-lo)/2
		switch {
		case nums[mid] == target:
			return mid
		case nums[mid] < target:
			lo = mid + 1
		default:
			hi = mid - 1
		}
	}
	return -1
}

// searchRotated 旋转数组二分：先判断哪一半有序，再看 target 是否落在有序的那一半。
func searchRotated(nums []int, target int) int {
	lo, hi := 0, len(nums)-1
	for lo <= hi {
		mid := lo + (hi-lo)/2
		if nums[mid] == target {
			return mid
		}
		if nums[lo] <= nums[mid] {
			if nums[lo] <= target && target < nums[mid] {
				hi = mid - 1
			} else {
				lo = mid + 1
			}
		} else {
			if nums[mid] < target && target <= nums[hi] {
				lo = mid + 1
			} else {
				hi = mid - 1
			}
		}
	}
	return -1
}

// lowerBound 返回第一个 >= target 的下标，全都更小时返回 len(nums)。区间是左闭右开 [lo, hi)。
func lowerBound(nums []int, target int) int {
	lo, hi := 0, len(nums)
	for lo < hi {
		mid := lo + (hi-lo)/2
		if nums[mid] < target {
			lo = mid + 1
		} else {
			hi = mid
		}
	}
	return lo
}

// searchRange 起止位置：左端用 lowerBound(target)，右端用 lowerBound(target+1) - 1。
func searchRange(nums []int, target int) []int {
	left := lowerBound(nums, target)
	if left == len(nums) || nums[left] != target {
		return []int{-1, -1}
	}
	return []int{left, lowerBound(nums, target+1) - 1}
}

// spiralOrder 螺旋矩阵：维护上下左右四条边界，走完一条边就收缩一格。
func spiralOrder(matrix [][]int) []int {
	if len(matrix) == 0 || len(matrix[0]) == 0 {
		return nil
	}
	top, bottom := 0, len(matrix)-1
	left, right := 0, len(matrix[0])-1
	res := make([]int, 0, len(matrix)*len(matrix[0]))
	for top <= bottom && left <= right {
		for c := left; c <= right; c++ {
			res = append(res, matrix[top][c])
		}
		top++
		for r := top; r <= bottom; r++ {
			res = append(res, matrix[r][right])
		}
		right--
		if top <= bottom {
			for c := right; c >= left; c-- {
				res = append(res, matrix[bottom][c])
			}
			bottom--
		}
		if left <= right {
			for r := bottom; r >= top; r-- {
				res = append(res, matrix[r][left])
			}
			left++
		}
	}
	return res
}

// addStrings 字符串加法：从末位向前逐位相加，carry 保存进位，最后反转。
func addStrings(a, b string) string {
	res := make([]byte, 0, max(len(a), len(b))+1)
	i, j, carry := len(a)-1, len(b)-1, 0
	for i >= 0 || j >= 0 || carry > 0 {
		sum := carry
		if i >= 0 {
			sum += int(a[i] - '0')
			i--
		}
		if j >= 0 {
			sum += int(b[j] - '0')
			j--
		}
		res = append(res, byte(sum%10)+'0')
		carry = sum / 10
	}
	for l, r := 0, len(res)-1; l < r; l, r = l+1, r-1 {
		res[l], res[r] = res[r], res[l]
	}
	return string(res)
}

// nextPermutation 下一个排列：从后找第一个升序对 i，与其后“刚好更大”的数交换，再反转后缀。
func nextPermutation(nums []int) {
	i := len(nums) - 2
	for i >= 0 && nums[i] >= nums[i+1] {
		i--
	}
	if i >= 0 {
		j := len(nums) - 1
		for nums[j] <= nums[i] {
			j--
		}
		nums[i], nums[j] = nums[j], nums[i]
	}
	reverse(nums[i+1:])
}

// reverse 原地反转切片。
func reverse(nums []int) {
	for l, r := 0, len(nums)-1; l < r; l, r = l+1, r-1 {
		nums[l], nums[r] = nums[r], nums[l]
	}
}

// maxDepth 递归三步：终止条件、递归左右子树、合并结果。
func maxDepth(root *TreeNode) int {
	if root == nil {
		return 0
	}
	return 1 + max(maxDepth(root.Left), maxDepth(root.Right))
}

// lowestCommonAncestor 后序递归：左右子树各找到一个目标时，当前节点就是最近公共祖先。
func lowestCommonAncestor(root, p, q *TreeNode) *TreeNode {
	if root == nil || root == p || root == q {
		return root
	}
	left := lowestCommonAncestor(root.Left, p, q)
	right := lowestCommonAncestor(root.Right, p, q)
	if left != nil && right != nil {
		return root
	}
	if left != nil {
		return left
	}
	return right
}

// isValidBST 带上下界递归：每个节点的值必须严格落在 lo 节点和 hi 节点的值之间，nil 表示没有界。
func isValidBST(root *TreeNode) bool {
	return validate(root, nil, nil)
}

// validate 检查 root 子树的所有节点是否都在 (lo.Val, hi.Val) 内，lo 或 hi 为 nil 时该侧不设限。
func validate(root, lo, hi *TreeNode) bool {
	if root == nil {
		return true
	}
	if lo != nil && root.Val <= lo.Val {
		return false
	}
	if hi != nil && root.Val >= hi.Val {
		return false
	}
	return validate(root.Left, lo, root) && validate(root.Right, root, hi)
}

// levelOrder 层序遍历：每轮先记下当前队列长度 size，只处理这 size 个节点。
func levelOrder(root *TreeNode) [][]int {
	var res [][]int
	if root == nil {
		return res
	}
	queue := []*TreeNode{root}
	for len(queue) > 0 {
		size := len(queue)
		level := make([]int, 0, size)
		for i := 0; i < size; i++ {
			node := queue[i]
			level = append(level, node.Val)
			if node.Left != nil {
				queue = append(queue, node.Left)
			}
			if node.Right != nil {
				queue = append(queue, node.Right)
			}
		}
		queue = queue[size:]
		res = append(res, level)
	}
	return res
}

// numIslands 网格 DFS：遇到 '1' 就计数，并把整片相连的陆地沉成 '0'。
func numIslands(grid [][]byte) int {
	count := 0
	for r := range grid {
		for c := range grid[r] {
			if grid[r][c] == '1' {
				count++
				sink(grid, r, c)
			}
		}
	}
	return count
}

// sink 从 (r, c) 出发把相连的陆地都改成 '0'，越界或不是陆地时直接返回。
func sink(grid [][]byte, r, c int) {
	if r < 0 || r >= len(grid) || c < 0 || c >= len(grid[r]) || grid[r][c] != '1' {
		return
	}
	grid[r][c] = '0'
	sink(grid, r+1, c)
	sink(grid, r-1, c)
	sink(grid, r, c+1)
	sink(grid, r, c-1)
}

// canFinish 拓扑排序（Kahn）：入度为 0 的课先修，修完后减少后继课程的入度。
func canFinish(numCourses int, prerequisites [][]int) bool {
	indegree := make([]int, numCourses)
	next := make([][]int, numCourses)
	for _, p := range prerequisites {
		course, pre := p[0], p[1]
		next[pre] = append(next[pre], course)
		indegree[course]++
	}
	queue := []int{}
	for i, d := range indegree {
		if d == 0 {
			queue = append(queue, i)
		}
	}
	done := 0
	for len(queue) > 0 {
		cur := queue[0]
		queue = queue[1:]
		done++
		for _, nx := range next[cur] {
			indegree[nx]--
			if indegree[nx] == 0 {
				queue = append(queue, nx)
			}
		}
	}
	return done == numCourses
}

// quickSort 原地快速排序：选基准、双指针分区、递归两半。基准取中间元素，避开有序数组的最坏情况。
func quickSort(nums []int) {
	if len(nums) < 2 {
		return
	}
	pivot := nums[len(nums)/2]
	i, j := 0, len(nums)-1
	for i <= j {
		for nums[i] < pivot {
			i++
		}
		for nums[j] > pivot {
			j--
		}
		if i <= j {
			nums[i], nums[j] = nums[j], nums[i]
			i++
			j--
		}
	}
	quickSort(nums[:j+1])
	quickSort(nums[i:])
}

// findKthLargest 快速选择：第 k 大就是升序后下标 len-k 的元素，每轮只递归含目标下标的一侧。会改动入参。
func findKthLargest(nums []int, k int) int {
	target := len(nums) - k
	lo, hi := 0, len(nums)-1
	for lo < hi {
		pivot := nums[lo+(hi-lo)/2]
		i, j := lo, hi
		for i <= j {
			for nums[i] < pivot {
				i++
			}
			for nums[j] > pivot {
				j--
			}
			if i <= j {
				nums[i], nums[j] = nums[j], nums[i]
				i++
				j--
			}
		}
		switch {
		case target <= j:
			hi = j
		case target >= i:
			lo = i
		default:
			return nums[target]
		}
	}
	return nums[target]
}

// minHeap 实现 container/heap.Interface：Go 手写堆必须背的五个方法。
type minHeap []int

func (h minHeap) Len() int           { return len(h) }
func (h minHeap) Less(i, j int) bool { return h[i] < h[j] }
func (h minHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *minHeap) Push(x any)        { *h = append(*h, x.(int)) }
func (h *minHeap) Pop() any {
	old := *h
	x := old[len(old)-1]
	*h = old[:len(old)-1]
	return x
}

// findKthLargestHeap 小顶堆：堆里只保留最大的 k 个数，堆顶就是第 k 大。
func findKthLargestHeap(nums []int, k int) int {
	h := &minHeap{}
	for _, x := range nums {
		heap.Push(h, x)
		if h.Len() > k {
			heap.Pop(h)
		}
	}
	return (*h)[0]
}

// mergeIntervals 先按起点排序，再依次判断是否与结果里最后一个区间重叠。
// 会按起点重排入参切片（区间本身不会被改动，结果是拷贝）。
func mergeIntervals(intervals [][]int) [][]int {
	sort.Slice(intervals, func(i, j int) bool { return intervals[i][0] < intervals[j][0] })
	var res [][]int
	for _, cur := range intervals {
		if n := len(res); n > 0 && cur[0] <= res[n-1][1] {
			res[n-1][1] = max(res[n-1][1], cur[1])
		} else {
			res = append(res, []int{cur[0], cur[1]})
		}
	}
	return res
}

// entry 是 LRU 双向链表的节点。
type entry struct {
	key, val   int
	prev, next *entry
}

// LRUCache 哈希表加双向链表：哈希表 O(1) 定位节点，链表维护使用顺序（头部最新，尾部最久）。
type LRUCache struct {
	capacity   int
	items      map[int]*entry
	head, tail *entry // 哨兵节点，真实数据在它们之间
}

// NewLRUCache 创建容量为 capacity 的缓存，并把两个哨兵节点连起来。
func NewLRUCache(capacity int) *LRUCache {
	head, tail := &entry{}, &entry{}
	head.next, tail.prev = tail, head
	return &LRUCache{capacity: capacity, items: make(map[int]*entry), head: head, tail: tail}
}

// Get 命中时把节点移到头部并返回值，未命中返回 -1。
func (c *LRUCache) Get(key int) int {
	e, ok := c.items[key]
	if !ok {
		return -1
	}
	c.moveToFront(e)
	return e.val
}

// Put 已存在则更新并移到头部；不存在则插入头部，超出容量时淘汰尾部节点。
func (c *LRUCache) Put(key, val int) {
	if e, ok := c.items[key]; ok {
		e.val = val
		c.moveToFront(e)
		return
	}
	e := &entry{key: key, val: val}
	c.items[key] = e
	c.addToFront(e)
	if len(c.items) > c.capacity {
		last := c.tail.prev
		c.remove(last)
		delete(c.items, last.key)
	}
}

// moveToFront 先摘下节点再插到头部。
func (c *LRUCache) moveToFront(e *entry) {
	c.remove(e)
	c.addToFront(e)
}

// addToFront 把节点插到头哨兵之后。
func (c *LRUCache) addToFront(e *entry) {
	e.prev, e.next = c.head, c.head.next
	c.head.next.prev = e
	c.head.next = e
}

// remove 把节点从链表中摘下，不动哈希表。
func (c *LRUCache) remove(e *entry) {
	e.prev.next = e.next
	e.next.prev = e.prev
}

// MinStack 辅助栈同步记录“到当前位置为止的最小值”。
type MinStack struct {
	stack []int
	mins  []int
}

// NewMinStack 创建空栈。
func NewMinStack() *MinStack { return &MinStack{} }

// Push 入栈，同时压入新的最小值。
func (s *MinStack) Push(x int) {
	m := x
	if len(s.mins) > 0 {
		m = min(x, s.mins[len(s.mins)-1])
	}
	s.stack = append(s.stack, x)
	s.mins = append(s.mins, m)
}

// Pop 两个栈同步弹出。
func (s *MinStack) Pop() {
	s.stack = s.stack[:len(s.stack)-1]
	s.mins = s.mins[:len(s.mins)-1]
}

// Top 返回栈顶元素。
func (s *MinStack) Top() int { return s.stack[len(s.stack)-1] }

// GetMin 返回当前最小值，O(1)。
func (s *MinStack) GetMin() int { return s.mins[len(s.mins)-1] }

// permute 回溯排列：用 used 标记已选元素，path 是当前路径，选满即收集（必须复制 path）。
func permute(nums []int) [][]int {
	var res [][]int
	used := make([]bool, len(nums))
	path := make([]int, 0, len(nums))
	var dfs func()
	dfs = func() {
		if len(path) == len(nums) {
			res = append(res, append([]int{}, path...))
			return
		}
		for i, x := range nums {
			if used[i] {
				continue
			}
			used[i] = true
			path = append(path, x)
			dfs()
			path = path[:len(path)-1]
			used[i] = false
		}
	}
	dfs()
	return res
}

// subsets 回溯子集：每个节点都是一个答案；用 start 保证只往后选，避免重复。
func subsets(nums []int) [][]int {
	var res [][]int
	path := []int{}
	var dfs func(start int)
	dfs = func(start int) {
		res = append(res, append([]int{}, path...))
		for i := start; i < len(nums); i++ {
			path = append(path, nums[i])
			dfs(i + 1)
			path = path[:len(path)-1]
		}
	}
	dfs(0)
	return res
}

// generateParenthesis 括号生成：左括号还有余量就放左，右括号数量少于左括号才能放右。
func generateParenthesis(n int) []string {
	var res []string
	var dfs func(path []byte, open, closed int)
	dfs = func(path []byte, open, closed int) {
		if len(path) == 2*n {
			res = append(res, string(path))
			return
		}
		if open < n {
			dfs(append(path, '('), open+1, closed)
		}
		if closed < open {
			dfs(append(path, ')'), open, closed+1)
		}
	}
	dfs(make([]byte, 0, 2*n), 0, 0)
	return res
}

// maxSubArray 以 i 结尾的最大和：要么接在前面子数组的后面，要么从自己重新开始。
func maxSubArray(nums []int) int {
	best, cur := nums[0], nums[0]
	for _, x := range nums[1:] {
		cur = max(x, cur+x)
		best = max(best, cur)
	}
	return best
}

// climbStairs f(n) = f(n-1) + f(n-2)，f(0)=f(1)=1，只需要滚动两个变量。
func climbStairs(n int) int {
	a, b := 1, 1
	for i := 2; i <= n; i++ {
		a, b = b, a+b
	}
	return b
}

// lengthOfLIS dp[i] 表示以 nums[i] 结尾的最长上升子序列长度，O(n^2)。
func lengthOfLIS(nums []int) int {
	dp := make([]int, len(nums))
	best := 0
	for i := range nums {
		dp[i] = 1
		for j := 0; j < i; j++ {
			if nums[j] < nums[i] {
				dp[i] = max(dp[i], dp[j]+1)
			}
		}
		best = max(best, dp[i])
	}
	return best
}

// longestCommonSubsequence 二维 dp：dp[i][j] 是 a[:i] 与 b[:j] 的最长公共子序列长度。
func longestCommonSubsequence(a, b string) int {
	dp := make([][]int, len(a)+1)
	for i := range dp {
		dp[i] = make([]int, len(b)+1)
	}
	for i := 1; i <= len(a); i++ {
		for j := 1; j <= len(b); j++ {
			if a[i-1] == b[j-1] {
				dp[i][j] = dp[i-1][j-1] + 1
			} else {
				dp[i][j] = max(dp[i-1][j], dp[i][j-1])
			}
		}
	}
	return dp[len(a)][len(b)]
}
